import itertools
from reduce import reduce

def sat_solve(inst):
    m = inst["num_vars"]
    clauses = inst["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for cl in clauses:
            if not any((bits[abs(l)-1] if l > 0 else not bits[abs(l)-1]) for l in cl):
                ok = False
                break
        if ok:
            return True
    return False

def ss_solve(inst):
    nums = inst["numbers"]
    t = inst["target"]
    # meet in middle for small
    reach = {0}
    for a in nums:
        reach |= {x + a for x in reach}
    return t in reach

def all_clauses(m):
    res = []
    for combo in itertools.combinations(range(1, m+1), 3):
        for signs in itertools.product([1,-1], repeat=3):
            res.append([combo[i]*signs[i] for i in range(3)])
    return res

